import { Ajv, type ValidateFunction } from "ajv";
import {
  DEFAULT_PROJECTION,
  toolSchemas,
  type ProjectionSettings,
} from "./context.js";
import type {
  AssistantMessage,
  JsonValue,
  Llm,
  UnifiedRequest,
} from "./protocol.js";
import type { Context } from "./runtime.js";
import {
  buildRequest,
  replayTrace,
  SESSION_LOG,
  type SessionEvent,
  type SessionLog,
  type TraceItem,
} from "./session.js";

export interface RunTurnResult {
  finalMessage: AssistantMessage;
  steps: number;
  turnId: string;
  stepIds: string[];
  trace: TraceItem[];
  requests: UnifiedRequest[];
}

export interface CheckpointProposal {
  summary: string;
  coveredThroughEventId: number;
}

export interface AgentOptions {
  llm: Llm;
  context: Context;
  systemPrompt: string;
  dynamicContext?: (step: number) => string;
  projection?: ProjectionSettings;
  checkpointBeforeStep?: (input: {
    step: number;
    events: readonly SessionEvent[];
  }) => CheckpointProposal | undefined;
  maxSteps?: number;
}

export class Agent {
  readonly #llm: Llm;
  readonly #context: Context;
  readonly #validators = new Map<string, { schema: string; validate: ValidateFunction }>();
  readonly #ajv = new Ajv({ allErrors: true, strict: false });
  readonly #systemPrompt: string;
  readonly #dynamicContext: (step: number) => string;
  readonly #maxSteps: number;
  readonly #projection: ProjectionSettings;
  readonly #session: SessionLog;
  readonly #checkpointBeforeStep?: AgentOptions["checkpointBeforeStep"];

  constructor(options: AgentOptions) {
    this.#llm = options.llm;
    this.#context = options.context;
    this.#systemPrompt = options.systemPrompt;
    this.#dynamicContext = options.dynamicContext ?? ((step) => `Current step: ${step}`);
    this.#maxSteps = options.maxSteps ?? 8;
    this.#projection = options.projection ?? DEFAULT_PROJECTION;
    this.#session = this.#context.use(SESSION_LOG);
    this.#checkpointBeforeStep = options.checkpointBeforeStep;
  }

  async runTurn(userInput: string): Promise<RunTurnResult> {
    const eventStart = this.#session.events.length;
    const turnId = this.#session.nextTurnId();
    this.#session.append({ type: "turn/start", turnId });
    this.#session.append({ type: "user/message", turnId, content: userInput });
    const requests: UnifiedRequest[] = [];
    const stepIds: string[] = [];

    for (let step = 1; step <= this.#maxSteps; step += 1) {
      const checkpoint = this.#checkpointBeforeStep?.({ step, events: this.#session.events });
      if (checkpoint) {
        this.#session.checkpoint(checkpoint.summary, checkpoint.coveredThroughEventId);
      }
      const stepId = `${turnId}-step-${step}`;
      stepIds.push(stepId);
      this.#session.append({ type: "step/start", turnId, stepId, ordinal: step });
      this.#session.append({
        type: "request/header",
        stepId,
        provider: this.#llm.provider,
        model: this.#llm.model,
        system: this.#context.compilePrompt(this.#systemPrompt),
        tools: toolSchemas(this.#context.listTools()),
        dynamicContext: this.#dynamicContext(step),
        projection: this.#projection,
      });
      const request = buildRequest(this.#session.events, stepId);
      requests.push(structuredClone(request));

      const response = await this.#llm.complete(request);
      const assistant = response.message;
      this.#session.append({ type: "assistant/message", stepId, content: assistant.content });
      for (const call of assistant.toolCalls) {
        this.#session.append({ type: "tool/call", stepId, call });
      }

      if (assistant.toolCalls.length === 0) {
        this.#session.append({ type: "step/end", stepId, outcome: "complete" });
        this.#session.append({ type: "turn/end", turnId, outcome: "completed" });
        return {
          finalMessage: assistant,
          steps: step,
          turnId,
          stepIds,
          trace: replayTrace(this.#session.events.slice(eventStart)),
          requests,
        };
      }

      for (const call of assistant.toolCalls) {
        const result = await this.#executeTool(call.name, call.arguments);
        this.#session.append({
          type: "tool/result",
          stepId,
          toolCallId: call.id,
          name: call.name,
          content: JSON.stringify(result),
        });
      }
      this.#session.append({ type: "step/end", stepId, outcome: "tool-calls" });
    }

    this.#session.append({ type: "turn/end", turnId, outcome: "max-steps" });
    throw new Error(`Agent exceeded maxSteps (${this.#maxSteps}) before finishing the turn.`);
  }

  async #executeTool(name: string, input: JsonValue): Promise<JsonValue> {
    const tool = this.#context.getTool(name);
    if (!tool) return { ok: false, error: `Unknown tool: ${name}` };
    const schema = JSON.stringify(tool.inputSchema);
    const cached = this.#validators.get(name);
    const validate = cached?.schema === schema ? cached.validate : this.#ajv.compile(tool.inputSchema);
    this.#validators.set(name, { schema, validate });
    if (!validate?.(input)) {
      return {
        ok: false,
        error: "Invalid tool arguments",
        issues: (validate?.errors ?? []).map((error) => `${error.instancePath || "/"} ${error.message}`),
      };
    }
    try {
      const result = await tool.execute(input);
      this.#context.emit("tool/executed", { name, input, result });
      return result;
    } catch (error) {
      return { ok: false, error: error instanceof Error ? error.message : String(error) };
    }
  }
}

import type { ModelMessage, ToolMessage, ToolSchema, UnifiedRequest } from "./protocol.js";

export interface ProjectionSettings {
  maxToolResultChars: number;
  toolResultHeadChars: number;
  toolResultTailChars: number;
}

export const DEFAULT_PROJECTION: ProjectionSettings = {
  maxToolResultChars: 720,
  toolResultHeadChars: 430,
  toolResultTailChars: 170,
};

export interface RequestPart {
  id: string;
  kind: "system" | "tools" | "message" | "dynamic";
  stability: "stable" | "append-only" | "step-variable";
  label: string;
  value: unknown;
  approximateTokens: number;
}

export interface PrefixComparison {
  sharedParts: number;
  sharedApproximateTokens: number;
  previousParts: number;
  currentParts: number;
  firstInvalidation: string | null;
  note: string;
}

export interface ClippedToolResult {
  content: string;
  omittedCharacters: number;
}

export function projectMessages(
  messages: ModelMessage[],
  settings: ProjectionSettings = DEFAULT_PROJECTION,
): ModelMessage[] {
  return messages.map((message) => {
    if (message.role !== "tool") return structuredClone(message);
    const clipped = clipToolResult(message.content, settings);
    return { ...message, content: clipped.content } satisfies ToolMessage;
  });
}

export function clipToolResult(
  content: string,
  settings: ProjectionSettings = DEFAULT_PROJECTION,
): ClippedToolResult {
  if (content.length <= settings.maxToolResultChars) {
    return { content, omittedCharacters: 0 };
  }
  const omittedCharacters = Math.max(
    0,
    content.length - settings.toolResultHeadChars - settings.toolResultTailChars,
  );
  const marker = `\n[… ${omittedCharacters} characters omitted from the model projection …]\n`;
  return {
    content:
      content.slice(0, settings.toolResultHeadChars) +
      marker +
      content.slice(content.length - settings.toolResultTailChars),
    omittedCharacters,
  };
}

export function describeRequest(request: UnifiedRequest): RequestPart[] {
  const parts: RequestPart[] = [
    part("system", "system", "stable", "System prompt", request.system),
    part("tools", "tools", "stable", "Tool schemas", request.tools),
  ];
  for (const [index, message] of request.messages.entries()) {
    const suffix = message.role === "tool" ? ` · ${message.name}` : "";
    parts.push(
      part(
        `message-${index}`,
        "message",
        "append-only",
        `${message.role}${suffix}`,
        message,
      ),
    );
  }
  if (request.dynamicContext) {
    parts.push(
      part(
        "dynamic",
        "dynamic",
        "step-variable",
        "Step context",
        request.dynamicContext,
      ),
    );
  }
  return parts;
}

export function compareRequestPrefix(
  previous: UnifiedRequest | undefined,
  current: UnifiedRequest,
): PrefixComparison {
  const currentParts = describeRequest(current);
  if (!previous) {
    return {
      sharedParts: 0,
      sharedApproximateTokens: 0,
      previousParts: 0,
      currentParts: currentParts.length,
      firstInvalidation: "First request has no predecessor.",
      note: "Teaching estimate only; no provider cache was queried.",
    };
  }
  const previousParts = describeRequest(previous);
  let sharedParts = 0;
  while (
    sharedParts < previousParts.length &&
    sharedParts < currentParts.length &&
    canonical(previousParts[sharedParts]?.value) === canonical(currentParts[sharedParts]?.value)
  ) {
    sharedParts += 1;
  }
  return {
    sharedParts,
    sharedApproximateTokens: currentParts
      .slice(0, sharedParts)
      .reduce((total, item) => total + item.approximateTokens, 0),
    previousParts: previousParts.length,
    currentParts: currentParts.length,
    firstInvalidation:
      sharedParts === Math.min(previousParts.length, currentParts.length)
        ? null
        : currentParts[sharedParts]?.label ?? "Request end",
    note: "Longest identical canonical prefix; approximate tokens, not provider cache usage.",
  };
}

export function approximateTokens(value: unknown): number {
  const text = typeof value === "string" ? value : canonical(value);
  return Math.max(1, Math.ceil([...text].length / 4));
}

export function toolSchemas(tools: Array<{ name: string; description: string; inputSchema: Record<string, unknown> }>): ToolSchema[] {
  return tools.map(({ name, description, inputSchema }) => ({ name, description, inputSchema }));
}

function part(
  id: string,
  kind: RequestPart["kind"],
  stability: RequestPart["stability"],
  label: string,
  value: unknown,
): RequestPart {
  return { id, kind, stability, label, value, approximateTokens: approximateTokens(value) };
}

function canonical(value: unknown): string {
  return JSON.stringify(sortObject(value));
}

function sortObject(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortObject);
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>)
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([key, item]) => [key, sortObject(item)]),
    );
  }
  return value;
}

import type { ToolDefinition } from "./protocol.js";

export class ServiceToken<T> {
  readonly key = Symbol();
  constructor(readonly name: string) {}
}

export interface Plugin {
  name: string;
  setup(context: Context): void | Promise<void>;
}

export interface RuntimeInspection {
  plugins: string[];
  services: Array<{ name: string; provider: string }>;
  tools: Array<{ name: string; plugin: string }>;
  prompts: Array<{ id: string; plugin: string; text: string }>;
  listeners: Array<{ event: string; plugin: string }>;
  relations: Array<{ consumer: string; service: string; provider: string }>;
}

type Disposer = () => void;
type Listener = (payload: unknown) => void;

interface MountRecord {
  name: string;
  effects: Disposer[];
  state: "installing" | "mounted" | "unmounted";
}

interface Owned<T> {
  owner: string;
  value: T;
}

export class Context {
  readonly #mounts = new Map<string, MountRecord>();
  readonly #services = new Map<symbol, Owned<unknown> & { token: ServiceToken<unknown> }>();
  readonly #tools = new Map<string, Owned<ToolDefinition>>();
  readonly #prompts = new Map<string, Owned<string>>();
  readonly #listeners = new Map<string, Set<Owned<Listener>>>();
  readonly #relations: RuntimeInspection["relations"] = [];
  #activeMount: MountRecord | null = null;

  async mount(plugin: Plugin): Promise<Disposer> {
    if (this.#mounts.has(plugin.name)) throw new Error(`Plugin already mounted: ${plugin.name}`);
    if (this.#activeMount) throw new Error("Nested plugin mounting is not supported during setup.");
    const record: MountRecord = { name: plugin.name, effects: [], state: "installing" };
    this.#mounts.set(plugin.name, record);
    this.#activeMount = record;
    try {
      await plugin.setup(this);
      record.state = "mounted";
    } catch (error) {
      this.#rollback(record);
      this.#mounts.delete(plugin.name);
      throw error;
    } finally {
      this.#activeMount = null;
    }

    this.emit("runtime/plugin-mounted", { plugin: plugin.name });
    return once(() => {
      if (record.state === "unmounted") return;
      this.emit("runtime/plugin-unmounting", { plugin: plugin.name });
      this.#rollback(record);
      this.#mounts.delete(plugin.name);
      this.#relations.splice(
        0,
        this.#relations.length,
        ...this.#relations.filter(
          (relation) => relation.consumer !== plugin.name && relation.provider !== plugin.name,
        ),
      );
      this.emit("runtime/plugin-unmounted", { plugin: plugin.name });
    });
  }

  effect(cleanup: Disposer): Disposer {
    const mount = this.#requireMount();
    const dispose = once(cleanup);
    mount.effects.push(dispose);
    return dispose;
  }

  provide<T>(token: ServiceToken<T>, value: T): Disposer {
    const owner = this.#requireMount().name;
    if (this.#services.has(token.key)) throw new Error(`Service already provided: ${token.name}`);
    this.#services.set(token.key, { owner, value, token: token as ServiceToken<unknown> });
    return this.effect(() => {
      const service = this.#services.get(token.key);
      if (service?.owner === owner) this.#services.delete(token.key);
    });
  }

  use<T>(token: ServiceToken<T>): T {
    const service = this.#services.get(token.key);
    if (!service) throw new Error(`Missing service: ${token.name}`);
    const consumer = this.#activeMount?.name;
    if (consumer) {
      const relation = { consumer, service: token.name, provider: service.owner };
      if (!this.#relations.some((item) => sameRelation(item, relation))) this.#relations.push(relation);
    }
    return service.value as T;
  }

  registerTool(tool: ToolDefinition): Disposer {
    const owner = this.#requireMount().name;
    if (this.#tools.has(tool.name)) throw new Error(`Tool already registered: ${tool.name}`);
    this.#tools.set(tool.name, { owner, value: tool });
    return this.effect(() => {
      if (this.#tools.get(tool.name)?.owner === owner) this.#tools.delete(tool.name);
    });
  }

  contributePrompt(id: string, text: string): Disposer {
    const owner = this.#requireMount().name;
    if (this.#prompts.has(id)) throw new Error(`Prompt contribution already registered: ${id}`);
    this.#prompts.set(id, { owner, value: text });
    return this.effect(() => {
      if (this.#prompts.get(id)?.owner === owner) this.#prompts.delete(id);
    });
  }

  on(event: string, listener: Listener): Disposer {
    const owner = this.#requireMount().name;
    const entry = { owner, value: listener };
    const listeners = this.#listeners.get(event) ?? new Set<Owned<Listener>>();
    listeners.add(entry);
    this.#listeners.set(event, listeners);
    return this.effect(() => {
      listeners.delete(entry);
      if (listeners.size === 0) this.#listeners.delete(event);
    });
  }

  emit(event: string, payload: unknown): void {
    for (const listener of [...(this.#listeners.get(event) ?? [])]) listener.value(payload);
  }

  listTools(): ToolDefinition[] {
    return [...this.#tools.values()].map((entry) => entry.value);
  }

  getTool(name: string): ToolDefinition | undefined {
    return this.#tools.get(name)?.value;
  }

  compilePrompt(base = ""): string {
    return [base, ...[...this.#prompts.values()].map((entry) => entry.value)]
      .filter(Boolean)
      .join("\n\n");
  }

  inspect(): RuntimeInspection {
    return {
      plugins: [...this.#mounts.values()]
        .filter((mount) => mount.state === "mounted")
        .map((mount) => mount.name),
      services: [...this.#services.values()].map((entry) => ({
        name: entry.token.name,
        provider: entry.owner,
      })),
      tools: [...this.#tools.entries()].map(([name, entry]) => ({ name, plugin: entry.owner })),
      prompts: [...this.#prompts.entries()].map(([id, entry]) => ({
        id,
        plugin: entry.owner,
        text: entry.value,
      })),
      listeners: [...this.#listeners.entries()].flatMap(([event, entries]) =>
        [...entries].map((entry) => ({ event, plugin: entry.owner })),
      ),
      relations: structuredClone(this.#relations),
    };
  }

  #requireMount(): MountRecord {
    if (!this.#activeMount) throw new Error("Runtime contributions must be registered during plugin setup.");
    return this.#activeMount;
  }

  #rollback(record: MountRecord): void {
    const failures: unknown[] = [];
    for (const dispose of [...record.effects].reverse()) {
      try {
        dispose();
      } catch (error) {
        failures.push(error);
      }
    }
    record.state = "unmounted";
    if (failures.length > 0) throw new AggregateError(failures, `Failed to clean up ${record.name}`);
  }
}

function once(action: Disposer): Disposer {
  let done = false;
  return () => {
    if (done) return;
    done = true;
    action();
  };
}

function sameRelation(
  left: RuntimeInspection["relations"][number],
  right: RuntimeInspection["relations"][number],
): boolean {
  return (
    left.consumer === right.consumer &&
    left.service === right.service &&
    left.provider === right.provider
  );
}

import { projectMessages, type ProjectionSettings } from "./context.js";
import type {
  AssistantMessage,
  ModelMessage,
  ToolCall,
  ToolSchema,
  UnifiedRequest,
} from "./protocol.js";
import { ServiceToken, type Plugin } from "./runtime.js";

interface EventBase {
  id: number;
  type: string;
}

export type SessionEvent =
  | (EventBase & { type: "turn/start"; turnId: string })
  | (EventBase & { type: "user/message"; turnId: string; content: string })
  | (EventBase & { type: "step/start"; turnId: string; stepId: string; ordinal: number })
  | (EventBase & {
      type: "request/header";
      stepId: string;
      provider: string;
      model: string;
      system: string;
      tools: ToolSchema[];
      dynamicContext: string;
      projection: ProjectionSettings;
    })
  | (EventBase & { type: "assistant/message"; stepId: string; content: string })
  | (EventBase & { type: "tool/call"; stepId: string; call: ToolCall })
  | (EventBase & {
      type: "tool/result";
      stepId: string;
      toolCallId: string;
      name: string;
      content: string;
    })
  | (EventBase & {
      type: "context/checkpoint";
      summary: string;
      coveredThroughEventId: number;
    })
  | (EventBase & { type: "runtime/plugin-mounted"; plugin: string })
  | (EventBase & { type: "runtime/plugin-unmounted"; plugin: string })
  | (EventBase & { type: "step/end"; stepId: string; outcome: "tool-calls" | "complete" })
  | (EventBase & {
      type: "turn/end";
      turnId: string;
      outcome: "completed" | "max-steps" | "failed";
    })
  | (EventBase & {
      type: "goal/created";
      goalId: string;
      objective: string;
      maxRounds: number;
    })
  | (EventBase & {
      type: "goal/round-started";
      goalId: string;
      round: number;
      label: string;
    })
  | (EventBase & {
      type: "goal/status-changed";
      goalId: string;
      status: "active" | "completed" | "blocked" | "max-rounds";
      reason: string;
    });

export type NewSessionEvent = SessionEvent extends infer Event
  ? Event extends SessionEvent
    ? Omit<Event, "id">
    : never
  : never;

export interface TraceItem {
  eventId: number;
  type: SessionEvent["type"];
  title: string;
  detail: string;
}

export class SessionLog {
  readonly #events: SessionEvent[] = [];
  #nextId = 1;
  #nextTurn = 1;

  get events(): readonly SessionEvent[] {
    return this.#events;
  }

  append(event: NewSessionEvent): SessionEvent {
    const stored = { ...structuredClone(event), id: this.#nextId++ } as SessionEvent;
    this.#events.push(stored);
    return stored;
  }

  nextTurnId(): string {
    return `turn-${this.#nextTurn++}`;
  }

  checkpoint(summary: string, coveredThroughEventId: number): SessionEvent {
    if (coveredThroughEventId >= this.#nextId) {
      throw new Error("A checkpoint may cover only events that already exist.");
    }
    return this.append({ type: "context/checkpoint", summary, coveredThroughEventId });
  }
}

export const SESSION_LOG = new ServiceToken<SessionLog>("session-log");

export function sessionPlugin(log: SessionLog): Plugin {
  return {
    name: "session-log",
    setup(context) {
      context.provide(SESSION_LOG, log);
      context.on("runtime/plugin-mounted", (payload) => {
        const plugin = pluginName(payload);
        log.append({ type: "runtime/plugin-mounted", plugin });
      });
      context.on("runtime/plugin-unmounting", (payload) => {
        const plugin = pluginName(payload);
        log.append({ type: "runtime/plugin-unmounted", plugin });
      });
    },
  };
}

export function buildRequest(events: readonly SessionEvent[], stepId: string): UnifiedRequest {
  const headerIndex = events.findIndex(
    (event) => event.type === "request/header" && event.stepId === stepId,
  );
  if (headerIndex === -1) throw new Error(`Missing request/header for ${stepId}.`);
  const header = events[headerIndex];
  if (header?.type !== "request/header") throw new Error(`Invalid request header for ${stepId}.`);

  const prefix = events.slice(0, headerIndex);
  const checkpoint = [...prefix]
    .reverse()
    .find((event): event is Extract<SessionEvent, { type: "context/checkpoint" }> =>
      event.type === "context/checkpoint",
    );
  const projectedEvents = checkpoint
    ? prefix.filter((event) => event.id > checkpoint.coveredThroughEventId)
    : prefix;
  const messages: ModelMessage[] = [];
  if (checkpoint) {
    messages.push({
      role: "system",
      content: `[Context checkpoint through event ${checkpoint.coveredThroughEventId}]\n${checkpoint.summary}`,
    });
  }

  const callsByStep = new Map<string, ToolCall[]>();
  for (const event of projectedEvents) {
    if (event.type === "tool/call") {
      const calls = callsByStep.get(event.stepId) ?? [];
      calls.push(structuredClone(event.call));
      callsByStep.set(event.stepId, calls);
    }
  }
  for (const event of projectedEvents) {
    switch (event.type) {
      case "user/message":
        messages.push({ role: "user", content: event.content });
        break;
      case "assistant/message":
        messages.push({
          role: "assistant",
          content: event.content,
          toolCalls: callsByStep.get(event.stepId) ?? [],
        });
        break;
      case "tool/result":
        messages.push({
          role: "tool",
          toolCallId: event.toolCallId,
          name: event.name,
          content: event.content,
        });
        break;
      default:
        break;
    }
  }

  return {
    system: header.system,
    tools: structuredClone(header.tools),
    messages: projectMessages(messages, header.projection),
    dynamicContext: header.dynamicContext,
  };
}

export function requestStepIds(events: readonly SessionEvent[]): string[] {
  return events
    .filter((event): event is Extract<SessionEvent, { type: "request/header" }> =>
      event.type === "request/header",
    )
    .map((event) => event.stepId);
}

export function replayTrace(events: readonly SessionEvent[]): TraceItem[] {
  return events.map((event) => ({
    eventId: event.id,
    type: event.type,
    title: traceTitle(event),
    detail: traceDetail(event),
  }));
}

function traceTitle(event: SessionEvent): string {
  switch (event.type) {
    case "request/header":
      return `${event.stepId} → ${event.provider}/${event.model}`;
    case "tool/call":
      return `call ${event.call.name}`;
    case "tool/result":
      return `result ${event.name}`;
    case "runtime/plugin-mounted":
    case "runtime/plugin-unmounted":
      return event.plugin;
    case "goal/round-started":
      return `round ${event.round} · ${event.label}`;
    default:
      return event.type;
  }
}

function traceDetail(event: SessionEvent): string {
  switch (event.type) {
    case "user/message":
    case "assistant/message":
      return event.content;
    case "tool/call":
      return JSON.stringify(event.call.arguments);
    case "tool/result":
      return event.content;
    case "context/checkpoint":
      return `${event.summary} (covers through #${event.coveredThroughEventId})`;
    case "request/header":
      return `${event.tools.length} tools · dynamic=${event.dynamicContext}`;
    case "turn/end":
    case "step/end":
      return event.outcome;
    case "goal/created":
      return event.objective;
    case "goal/status-changed":
      return `${event.status}: ${event.reason}`;
    default:
      return "";
  }
}

function pluginName(payload: unknown): string {
  if (
    typeof payload === "object" &&
    payload !== null &&
    "plugin" in payload &&
    typeof payload.plugin === "string"
  ) {
    return payload.plugin;
  }
  throw new Error("Runtime plugin event is missing its plugin name.");
}

